window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-edde17bcdc076497"]={"versions": [{"id": "FIG-edde17bcdc076497", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm / Flussdiagramm zur Spezifikation des Verdrängungsmechanismus (<code>Displacement</code>) im Ereignisspeicher des AUTOSAR Diagnostic Event Managers (Dem) innerhalb der AUTOSAR Classic Platform (Diagnostic Services). Es modelliert die Auswertelogik kombinierter Verdrängungskriterien (<code>Combined displacement criteria processing</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangs- und Referenzentitäten:</strong></li>\n<li><code>reported event</code>: Neu gemeldetes Diagnoseereignis, das im Ereignisspeicher abgelegt werden soll.</li>\n<li><code>found entries</code> / <code>old event memory entry</code>: Bereits im Ereignisspeicher vorhandene Einträge.</li>\n<li><code>PriooldEvent</code>: Priorität und Zustandsattribute des bestehenden Eintrags.</li>\n<li><strong>Konfigurations- und Statusparameter:</strong></li>\n<li><code>DemOBDEventDisplacement</code>: Boolescher Konfigurationsparameter zur Aktivierung der OBD-spezifischen Filterstufe.</li>\n<li>OBD-spezifische Kriterien: <code>emission-related</code>, Vorhandensein von <code>Service $02 FreezeFrame</code>, <code>PendingDTC == 1</code>, <code>MIL ON</code>.</li>\n<li>Statusflags: <code>TestNotCompletedThis OperationCycle bit == 1</code>.</li>\n<li><code>Passive memory entries</code>: Einträge im passiven Fehlerspeicherzustand.</li>\n<li><strong>Knoten und Senken:</strong></li>\n<li>Startknoten (<code>Initial State</code>).</li>\n<li>Verzweigungsknoten / Decision Points zur Prioritäts- und Zustandsprüfung.</li>\n<li>Synchronisationsbalken (Merge-Node).</li>\n<li>Endzustände: <code>Old event memory entry removed</code> (Erfolgreiche Verdrängung) und <code>New event memory entry not possible</code> (Keine Verdrängung möglich).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Suche nach vorhandenen Speichereinträgen mit der niedrigsten Priorität (<code>Search entries with lowest priority</code>).</li>\n<li><strong>OBD-Filterung (aktiv wenn <code>DemOBDEventDisplacement == TRUE</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung, ob die Priorität des gemeldeten Ereignisses größer ist als die der gefundenen Einträge (<code>Priority of reported event &gt; priority of found entries?</code>).</li>\n<li>Falls <strong>Yes</strong>: Direkter Übergang zum Merge-Balken unter Umgehung des Filters.</li>\n<li>Falls <strong>NO</strong>: Gefundene Einträge ignorieren, die emissionsrelevant sind UND bei denen ein Service $02 FreezeFrame existiert, <code>PendingDTC == 1</code> oder <code>MIL ON</code> aktiv ist.</li>\n<li>Anschließende Prüfung: Verbleiben gefundene Einträge mit niedrigster Priorität (<code>Found entries with lowest priority left?</code>)? Falls <strong>No</strong>, Abbruch zu <code>Displace no entry</code>. Falls <strong>Yes</strong>, Weiterleitung zur Prioritätsprüfung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Globale Prioritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung: <code>Priority of reported event &gt;= pririty of found entries</code>?</li>\n<li>Falls <strong>No</strong>: Abbruch zu <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n<li>Falls <strong>Yes</strong>: Weiterleitung über Synchronisationsbalken zum nächsten Auswertungsschritt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kombinierte Verdrängungskriterien (Kandidatenprüfung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Suche nach passiven Einträgen unter den verbliebenen Kandidaten (<code>Search passive entries of found entries</code>).</li>\n<li>Verzweigung <code>Passive memory entries found?</code>:</li>\n<li>Falls <strong>Yes</strong>: Ältester gefundener Eintrag wird durch das gemeldete Ereignis verdrängt (<code>Displace oldest found entry with reported event</code>) -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>Priority of reported event &gt; priority of found entries?</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>PriooldEvent [TestNotCompletedThis OperationCycle bit == 1]</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Verhaltensdiagramm für die Implementierung des Verdrängungsalgorithmus im Dem-Ereignisspeicher bei voller Speicherbelegung.</p>\n<ul class=\"fig-list\">\n<li>Die OBD-Verdrängungsschutzlogik ist über das Konfigurationsflag <code>DemOBDEventDisplacement</code> schaltbar; wenn aktiv, schützt sie emissionsrelevante Fehler mit FreezeFrame, aktivem PendingDTC oder gesetzter MIL vor Verdrängung durch nieder- oder gleichwertige Ereignisse.</li>\n<li>Eine Verdrängung erfordert mindestens gleiche Priorität des neuen Ereignisses gegenüber Speicherinhalten.</li>\n<li>Bei gleicher Priorität gilt die Verdrängungsreihenfolge: passive Einträge vor aktiven Einträgen, gefolgt von Einträgen mit unvollständigem Testzyklus (<code>TestNotCompletedThis OperationCycle == 1</code>). Innerhalb der jeweils ermittelten Kandidatengruppe wird stets der älteste Eintrag verdrängt.</li>\n</ul>"}, {"id": "FIG-0ac78ec7876532d0", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm / Flussdiagramm zur Spezifikation des Verdrängungsmechanismus (<code>Displacement</code>) im Ereignisspeicher des AUTOSAR Diagnostic Event Managers (Dem) innerhalb der AUTOSAR Classic Platform (Diagnostic Services). Es modelliert die Auswertelogik kombinierter Verdrängungskriterien (<code>Combined displacement criteria processing</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangs- und Referenzentitäten:</strong></li>\n<li><code>reported event</code>: Neu gemeldetes Diagnoseereignis, das im Ereignisspeicher abgelegt werden soll.</li>\n<li><code>found entries</code> / <code>old event memory entry</code>: Bereits im Ereignisspeicher vorhandene Einträge.</li>\n<li><code>PriooldEvent</code>: Priorität und Zustandsattribute des bestehenden Eintrags.</li>\n<li><strong>Konfigurations- und Statusparameter:</strong></li>\n<li><code>DemOBDEventDisplacement</code>: Boolescher Konfigurationsparameter zur Aktivierung der OBD-spezifischen Filterstufe.</li>\n<li>OBD-spezifische Kriterien: <code>emission-related</code>, Vorhandensein von <code>Service $02 FreezeFrame</code>, <code>PendingDTC == 1</code>, <code>MIL ON</code>.</li>\n<li>Statusflags: <code>TestNotCompletedThis OperationCycle bit == 1</code>.</li>\n<li><code>Passive memory entries</code>: Einträge im passiven Fehlerspeicherzustand.</li>\n<li><strong>Knoten und Senken:</strong></li>\n<li>Startknoten (<code>Initial State</code>).</li>\n<li>Verzweigungsknoten / Decision Points zur Prioritäts- und Zustandsprüfung.</li>\n<li>Synchronisationsbalken (Merge-Node).</li>\n<li>Endzustände: <code>Old event memory entry removed</code> (Erfolgreiche Verdrängung) und <code>New event memory entry not possible</code> (Keine Verdrängung möglich).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Suche nach vorhandenen Speichereinträgen mit der niedrigsten Priorität (<code>Search entries with lowest priority</code>).</li>\n<li><strong>OBD-Filterung (aktiv wenn <code>DemOBDEventDisplacement == TRUE</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung, ob die Priorität des gemeldeten Ereignisses größer ist als die der gefundenen Einträge (<code>Priority of reported event &gt; priority of found entries?</code>).</li>\n<li>Falls <strong>Yes</strong>: Direkter Übergang zum Merge-Balken unter Umgehung des Filters.</li>\n<li>Falls <strong>NO</strong>: Gefundene Einträge ignorieren, die emissionsrelevant sind UND bei denen ein Service $02 FreezeFrame existiert, <code>PendingDTC == 1</code> oder <code>MIL ON</code> aktiv ist.</li>\n<li>Anschließende Prüfung: Verbleiben gefundene Einträge mit niedrigster Priorität (<code>Found entries with lowest priority left?</code>)? Falls <strong>No</strong>, Abbruch zu <code>Displace no entry</code>. Falls <strong>Yes</strong>, Weiterleitung zur Prioritätsprüfung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Globale Prioritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung: <code>Priority of reported event &gt;= pririty of found entries</code>?</li>\n<li>Falls <strong>No</strong>: Abbruch zu <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n<li>Falls <strong>Yes</strong>: Weiterleitung über Synchronisationsbalken zum nächsten Auswertungsschritt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kombinierte Verdrängungskriterien (Kandidatenprüfung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Suche nach passiven Einträgen unter den verbliebenen Kandidaten (<code>Search passive entries of found entries</code>).</li>\n<li>Verzweigung <code>Passive memory entries found?</code>:</li>\n<li>Falls <strong>Yes</strong>: Ältester gefundener Eintrag wird durch das gemeldete Ereignis verdrängt (<code>Displace oldest found entry with reported event</code>) -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>Priority of reported event &gt; priority of found entries?</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>PriooldEvent [TestNotCompletedThis OperationCycle bit == 1]</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Verhaltensdiagramm für die Implementierung des Verdrängungsalgorithmus im Dem-Ereignisspeicher bei voller Speicherbelegung.</p>\n<ul class=\"fig-list\">\n<li>Die OBD-Verdrängungsschutzlogik ist über das Konfigurationsflag <code>DemOBDEventDisplacement</code> schaltbar; wenn aktiv, schützt sie emissionsrelevante Fehler mit FreezeFrame, aktivem PendingDTC oder gesetzter MIL vor Verdrängung durch nieder- oder gleichwertige Ereignisse.</li>\n<li>Eine Verdrängung erfordert mindestens gleiche Priorität des neuen Ereignisses gegenüber Speicherinhalten.</li>\n<li>Bei gleicher Priorität gilt die Verdrängungsreihenfolge: passive Einträge vor aktiven Einträgen, gefolgt von Einträgen mit unvollständigem Testzyklus (<code>TestNotCompletedThis OperationCycle == 1</code>). Innerhalb der jeweils ermittelten Kandidatengruppe wird stets der älteste Eintrag verdrängt.</li>\n</ul>"}, {"id": "FIG-13bc282e60149a3d", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm / Flussdiagramm zur Spezifikation des Verdrängungsmechanismus (<code>Displacement</code>) im Ereignisspeicher des AUTOSAR Diagnostic Event Managers (Dem) innerhalb der AUTOSAR Classic Platform (Diagnostic Services). Es modelliert die Auswertelogik kombinierter Verdrängungskriterien (<code>Combined displacement criteria processing</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangs- und Referenzentitäten:</strong></li>\n<li><code>reported event</code>: Neu gemeldetes Diagnoseereignis, das im Ereignisspeicher abgelegt werden soll.</li>\n<li><code>found entries</code> / <code>old event memory entry</code>: Bereits im Ereignisspeicher vorhandene Einträge.</li>\n<li><code>PriooldEvent</code>: Priorität und Zustandsattribute des bestehenden Eintrags.</li>\n<li><strong>Konfigurations- und Statusparameter:</strong></li>\n<li><code>DemOBDEventDisplacement</code>: Boolescher Konfigurationsparameter zur Aktivierung der OBD-spezifischen Filterstufe.</li>\n<li>OBD-spezifische Kriterien: <code>emission-related</code>, Vorhandensein von <code>Service $02 FreezeFrame</code>, <code>PendingDTC == 1</code>, <code>MIL ON</code>.</li>\n<li>Statusflags: <code>Stored Event is NOT testComplete</code>.</li>\n<li><code>Passive memory entries</code>: Einträge im passiven Fehlerspeicherzustand.</li>\n<li><strong>Knoten und Senken:</strong></li>\n<li>Startknoten (<code>Initial State</code>).</li>\n<li>Verzweigungsknoten / Decision Points zur Prioritäts- und Zustandsprüfung.</li>\n<li>Synchronisationsbalken (Merge-Node).</li>\n<li>Endzustände: <code>Old event memory entry removed</code> (Erfolgreiche Verdrängung) und <code>New event memory entry not possible</code> (Keine Verdrängung möglich).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Suche nach vorhandenen Speichereinträgen mit der niedrigsten Priorität (<code>Search entries with lowest priority</code>).</li>\n<li><strong>OBD-Filterung (aktiv wenn <code>DemOBDEventDisplacement == TRUE</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung, ob die Priorität des gemeldeten Ereignisses größer ist als die der gefundenen Einträge (<code>Priority of reported event &gt; priority of found entries?</code>).</li>\n<li>Falls <strong>Yes</strong>: Direkter Übergang zum Merge-Balken unter Umgehung des Filters.</li>\n<li>Falls <strong>NO</strong>: Gefundene Einträge ignorieren, die emissionsrelevant sind UND bei denen ein Service $02 FreezeFrame existiert, <code>PendingDTC == 1</code> oder <code>MIL ON</code> aktiv ist.</li>\n<li>Anschließende Prüfung: Verbleiben gefundene Einträge mit niedrigster Priorität (<code>Found entries with lowest priority left?</code>)? Falls <strong>No</strong>, Abbruch zu <code>Displace no entry</code>. Falls <strong>Yes</strong>, Weiterleitung zur Prioritätsprüfung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Globale Prioritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung: <code>Priority of reported event &gt;= pririty of found entries</code>?</li>\n<li>Falls <strong>No</strong>: Abbruch zu <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n<li>Falls <strong>Yes</strong>: Weiterleitung über Synchronisationsbalken zum nächsten Auswertungsschritt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kombinierte Verdrängungskriterien (Kandidatenprüfung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Suche nach passiven Einträgen unter den verbliebenen Kandidaten (<code>Search passive entries of found entries</code>).</li>\n<li>Verzweigung <code>Passive memory entries found?</code>:</li>\n<li>Falls <strong>Yes</strong>: Ältester gefundener Eintrag wird durch das gemeldete Ereignis verdrängt (<code>Displace oldest found entry with reported event</code>) -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>Priority of reported event &gt; priority of found entries?</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>Stored Event is NOT testComplete</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Verhaltensdiagramm für die Implementierung des Verdrängungsalgorithmus im Dem-Ereignisspeicher bei voller Speicherbelegung.</p>\n<ul class=\"fig-list\">\n<li>Die OBD-Verdrängungsschutzlogik ist über das Konfigurationsflag <code>DemOBDEventDisplacement</code> schaltbar; wenn aktiv, schützt sie emissionsrelevante Fehler mit FreezeFrame, aktivem PendingDTC oder gesetzter MIL vor Verdrängung durch nieder- oder gleichwertige Ereignisse.</li>\n<li>Eine Verdrängung erfordert mindestens gleiche Priorität des neuen Ereignisses gegenüber Speicherinhalten.</li>\n<li>Bei gleicher Priorität gilt die Verdrängungsreihenfolge: passive Einträge vor aktiven Einträgen, gefolgt von Einträgen, deren Test im aktuellen Zyklus noch nicht abgeschlossen ist (<code>Stored Event is NOT testComplete</code>). Innerhalb der jeweils ermittelten Kandidatengruppe wird stets der älteste Eintrag verdrängt.</li>\n</ul>"}, {"id": "FIG-800a1defef110fdd", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm / Flussdiagramm zur Spezifikation des Verdrängungsmechanismus (<code>Displacement</code>) im Ereignisspeicher des AUTOSAR Diagnostic Event Managers (Dem) innerhalb der AUTOSAR Classic Platform (Diagnostic Services). Es modelliert die Auswertelogik kombinierter Verdrängungskriterien (<code>Combined displacement criteria processing</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangs- und Referenzentitäten:</strong></li>\n<li><code>reported event</code>: Neu gemeldetes Diagnoseereignis, das im Ereignisspeicher abgelegt werden soll.</li>\n<li><code>found entries</code> / <code>old event memory entry</code>: Bereits im Ereignisspeicher vorhandene Einträge.</li>\n<li><code>PriooldEvent</code>: Priorität und Zustandsattribute des bestehenden Eintrags.</li>\n<li><strong>Konfigurations- und Statusparameter:</strong></li>\n<li><code>DemOBDEventDisplacement</code>: Boolescher Konfigurationsparameter zur Aktivierung der OBD-spezifischen Filterstufe.</li>\n<li>OBD-spezifische Kriterien: <code>emission-related</code>, Vorhandensein von <code>Service $02 FreezeFrame</code>, <code>PendingDTC == 1</code>, <code>MIL ON</code>.</li>\n<li>Statusflags: <code>Stored Event is NOT testComplete</code>.</li>\n<li><code>Passive memory entries</code>: Einträge im passiven Fehlerspeicherzustand.</li>\n<li><strong>Knoten und Senken:</strong></li>\n<li>Startknoten (<code>Initial State</code>).</li>\n<li>Verzweigungsknoten / Decision Points zur Prioritäts- und Zustandsprüfung.</li>\n<li>Synchronisationsbalken (Merge-Node).</li>\n<li>Endzustände: <code>Old event memory entry removed</code> (Erfolgreiche Verdrängung) und <code>New event memory entry not possible</code> (Keine Verdrängung möglich).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Suche nach vorhandenen Speichereinträgen mit der niedrigsten Priorität (<code>Search entries with lowest priority</code>).</li>\n<li><strong>OBD-Filterung (aktiv wenn <code>DemOBDEventDisplacement == TRUE</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung, ob die Priorität des gemeldeten Ereignisses größer ist als die der gefundenen Einträge (<code>Priority of reported event &gt; priority of found entries?</code>).</li>\n<li>Falls <strong>Yes</strong>: Direkter Übergang zum Merge-Balken unter Umgehung des Filters.</li>\n<li>Falls <strong>NO</strong>: Gefundene Einträge ignorieren, die emissionsrelevant sind UND bei denen ein Service $02 FreezeFrame existiert, <code>PendingDTC == 1</code> oder <code>MIL ON</code> aktiv ist.</li>\n<li>Anschließende Prüfung: Verbleiben gefundene Einträge mit niedrigster Priorität (<code>Found entries with lowest priority left?</code>)? Falls <strong>No</strong>, Abbruch zu <code>Displace no entry</code>. Falls <strong>Yes</strong>, Weiterleitung zur Prioritätsprüfung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Globale Prioritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung: <code>Priority of reported event &gt;= pririty of found entries</code>?</li>\n<li>Falls <strong>No</strong>: Abbruch zu <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n<li>Falls <strong>Yes</strong>: Weiterleitung über Synchronisationsbalken zum nächsten Auswertungsschritt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kombinierte Verdrängungskriterien (Kandidatenprüfung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Suche nach passiven Einträgen unter den verbliebenen Kandidaten (<code>Search passive entries of found entries</code>).</li>\n<li>Verzweigung <code>Passive memory entries found?</code>:</li>\n<li>Falls <strong>Yes</strong>: Ältester gefundener Eintrag wird durch das gemeldete Ereignis verdrängt (<code>Displace oldest found entry with reported event</code>) -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>Priority of reported event &gt; priority of found entries?</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>Stored Event is NOT testComplete</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Verhaltensdiagramm für die Implementierung des Verdrängungsalgorithmus im Dem-Ereignisspeicher bei voller Speicherbelegung.</p>\n<ul class=\"fig-list\">\n<li>Die OBD-Verdrängungsschutzlogik ist über das Konfigurationsflag <code>DemOBDEventDisplacement</code> schaltbar; wenn aktiv, schützt sie emissionsrelevante Fehler mit FreezeFrame, aktivem PendingDTC oder gesetzter MIL vor Verdrängung durch nieder- oder gleichwertige Ereignisse.</li>\n<li>Eine Verdrängung erfordert mindestens gleiche Priorität des neuen Ereignisses gegenüber Speicherinhalten.</li>\n<li>Bei gleicher Priorität gilt die Verdrängungsreihenfolge: passive Einträge vor aktiven Einträgen, gefolgt von Einträgen, deren Test im aktuellen Zyklus noch nicht abgeschlossen ist (<code>Stored Event is NOT testComplete</code>). Innerhalb der jeweils ermittelten Kandidatengruppe wird stets der älteste Eintrag verdrängt.</li>\n</ul>"}, {"id": "FIG-5065182944608f84", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm / Flussdiagramm zur Spezifikation des Verdrängungsmechanismus (<code>Displacement</code>) im Ereignisspeicher des AUTOSAR Diagnostic Event Managers (Dem) innerhalb der AUTOSAR Classic Platform (Diagnostic Services). Es modelliert die Auswertelogik kombinierter Verdrängungskriterien (<code>Combined displacement criteria processing</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangs- und Referenzentitäten:</strong></li>\n<li><code>reported event</code>: Neu gemeldetes Diagnoseereignis, das im Ereignisspeicher abgelegt werden soll.</li>\n<li><code>found entries</code> / <code>old event memory entry</code>: Bereits im Ereignisspeicher vorhandene Einträge.</li>\n<li><code>PriooldEvent</code>: Priorität und Zustandsattribute des bestehenden Eintrags.</li>\n<li><strong>Konfigurations- und Statusparameter:</strong></li>\n<li><code>DemOBDEventDisplacement</code>: Boolescher Konfigurationsparameter zur Aktivierung der OBD-spezifischen Filterstufe.</li>\n<li>OBD-spezifische Kriterien: <code>emission-related</code>, Vorhandensein von <code>Service $02 FreezeFrame</code>, <code>PendingDTC == 1</code>, <code>MIL ON</code>.</li>\n<li>Statusflags: <code>Stored Event is NOT testComplete</code>.</li>\n<li><code>Passive memory entries</code>: Einträge im passiven Fehlerspeicherzustand.</li>\n<li><strong>Knoten und Senken:</strong></li>\n<li>Startknoten (<code>Initial State</code>).</li>\n<li>Verzweigungsknoten / Decision Points zur Prioritäts- und Zustandsprüfung.</li>\n<li>Synchronisationsbalken (Merge-Node).</li>\n<li>Endzustände: <code>Old event memory entry removed</code> (Erfolgreiche Verdrängung) und <code>New event memory entry not possible</code> (Keine Verdrängung möglich).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Suche nach vorhandenen Speichereinträgen mit der niedrigsten Priorität (<code>Search entries with lowest priority</code>).</li>\n<li><strong>OBD-Filterung (aktiv wenn <code>DemOBDEventDisplacement == TRUE</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung, ob die Priorität des gemeldeten Ereignisses größer ist als die der gefundenen Einträge (<code>Priority of reported event &gt; priority of found entries?</code>).</li>\n<li>Falls <strong>Yes</strong>: Direkter Übergang zum Merge-Balken unter Umgehung des Filters.</li>\n<li>Falls <strong>NO</strong>: Gefundene Einträge ignorieren, die emissionsrelevant sind UND bei denen ein Service $02 FreezeFrame existiert, <code>PendingDTC == 1</code> oder <code>MIL ON</code> aktiv ist.</li>\n<li>Anschließende Prüfung: Verbleiben gefundene Einträge mit niedrigster Priorität (<code>Found entries with lowest priority left?</code>)? Falls <strong>No</strong>, Abbruch zu <code>Displace no entry</code>. Falls <strong>Yes</strong>, Weiterleitung zur Prioritätsprüfung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Globale Prioritätsprüfung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung: <code>Priority of reported event &gt;= pririty of found entries</code>?</li>\n<li>Falls <strong>No</strong>: Abbruch zu <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n<li>Falls <strong>Yes</strong>: Weiterleitung über Synchronisationsbalken zum nächsten Auswertungsschritt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kombinierte Verdrängungskriterien (Kandidatenprüfung):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Suche nach passiven Einträgen unter den verbliebenen Kandidaten (<code>Search passive entries of found entries</code>).</li>\n<li>Verzweigung <code>Passive memory entries found?</code>:</li>\n<li>Falls <strong>Yes</strong>: Ältester gefundener Eintrag wird durch das gemeldete Ereignis verdrängt (<code>Displace oldest found entry with reported event</code>) -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>Priority of reported event &gt; priority of found entries?</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: Folgeprüfung <code>Stored Event is NOT testComplete</code>:</li>\n<li>Falls <strong>Yes</strong>: <code>Displace oldest found entry with reported event</code> -> <code>Old event memory entry removed</code>.</li>\n<li>Falls <strong>No</strong>: <code>Displace no entry</code> -> <code>New event memory entry not possible</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Verhaltensdiagramm für die Implementierung des Verdrängungsalgorithmus im Dem-Ereignisspeicher bei voller Speicherbelegung.</p>\n<ul class=\"fig-list\">\n<li>Die OBD-Verdrängungsschutzlogik ist über das Konfigurationsflag <code>DemOBDEventDisplacement</code> schaltbar; wenn aktiv, schützt sie emissionsrelevante Fehler mit FreezeFrame, aktivem PendingDTC oder gesetzter MIL vor Verdrängung durch nieder- oder gleichwertige Ereignisse.</li>\n<li>Eine Verdrängung erfordert mindestens gleiche Priorität des neuen Ereignisses gegenüber Speicherinhalten.</li>\n<li>Bei gleicher Priorität gilt die Verdrängungsreihenfolge: passive Einträge vor aktiven Einträgen, gefolgt von Einträgen, deren Test im aktuellen Zyklus noch nicht abgeschlossen ist (<code>Stored Event is NOT testComplete</code>). Innerhalb der jeweils ermittelten Kandidatengruppe wird stets der älteste Eintrag verdrängt.</li>\n</ul>"}], "trans": [{"from": "FIG-edde17bcdc076497", "to": "FIG-0ac78ec7876532d0", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0ac78ec7876532d0", "to": "FIG-13bc282e60149a3d", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Entscheidungsknoten rechts unten: Beschriftung von <code>PriooldEvent [TestNotCompletedThis OperationCycle bit == 1]</code> in <code>Stored Event is NOT testComplete</code> umbenannt.</li>\n</ul>"}, {"from": "FIG-13bc282e60149a3d", "to": "FIG-800a1defef110fdd", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Entscheidungsknoten <code>Priority of reported event &gt;= pririty of found entries</code>: Rote redaktionelle Markierung <code>A</code> rechts unterhalb der Raute eingefügt.</li>\n</ul>"}, {"from": "FIG-800a1defef110fdd", "to": "FIG-5065182944608f84", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
